css:
.fx-stk{width:min(680px,100%)}
.fx-stk .hint{opacity:.5;font-size:.85em;text-align:center;padding:1em 0}
.fx-stk .box{height:min(70vh,560px);overflow:auto;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface)}
.fx-stk h3{position:sticky;top:0;z-index:2;margin:0;padding:.55em 1.1em;font:700 .8em var(--font-body);letter-spacing:.14em;color:var(--primary);background:color-mix(in srgb,var(--primary) 9%,var(--surface));border-bottom:1px solid var(--border);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px)}
.fx-stk ul{list-style:none;margin:0;padding:0}
.fx-stk li{display:flex;align-items:center;gap:1em;padding:.8em 1.1em;border-bottom:1px solid var(--border)}
.fx-stk li:last-child{border-bottom:0}
.fx-stk .av{flex:none;width:2.6em;aspect-ratio:1;border-radius:50%;display:grid;place-items:center;font:700 .9em var(--font-heading);font-style:normal;color:var(--on-primary);background:var(--primary)}
.fx-stk li:nth-child(3n+2) .av{background:var(--accent);color:var(--on-accent)}
.fx-stk li:nth-child(3n) .av{background:var(--secondary);color:var(--on-primary)}
.fx-stk li b{display:block;font-weight:700}.fx-stk li span{font-size:.88em;opacity:.65}
